/**
 * Image stores (Phase 3f). Generated bytes never go into the repo: the memory
 * store keeps them for the run (dry-run, tests), the local store writes them
 * under a directory the CLI names (`--images-dir`, default `.cache/images`).
 * Neither is served by the site, so a run that writes a real database uses the
 * static store (Phase 5, Codex PR #86): it refuses every put, and the placeholder
 * adapter then records the deployed `/images/placeholder-brief.svg` instead of a
 * `/images/generated/...` path that would answer 404. A hosted store (Vercel Blob
 * or Supabase Storage) is a new external service and needs its own approval.
 */
import { mkdir, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import type { ImageMime, ImageStore, ImageStoreInput, StageContext } from "@cc/shared";

const EXTENSION: Record<ImageMime, string> = {
  "image/svg+xml": "svg",
  "image/png": "png",
  "image/jpeg": "jpg",
  "image/webp": "webp",
};

/** `/images/generated/<slug>/<variant>.<ext>`: a site-relative path the publisher can later rehost. */
export function imagePath(slug: string, variant: string, mime: ImageMime): string {
  const safeSlug = slug
    .split("/")
    .map((segment) => segment.replace(/[^A-Za-z0-9._-]+/g, "-").replace(/^[.-]+|[.-]+$/g, ""))
    .filter(Boolean)
    .join("/");
  const safeVariant = variant.replace(/[^A-Za-z0-9_-]+/g, "-") || "hero";
  if (!safeSlug) throw new Error("IMAGE_STORE_SLUG_INVALID: empty slug");
  return `/images/generated/${safeSlug}/${safeVariant}.${EXTENSION[mime]}`;
}

export class MemoryImageStore implements ImageStore {
  readonly kind = "memory";
  readonly files = new Map<string, { bytes: Uint8Array; mime: ImageMime }>();

  async put(input: ImageStoreInput, _ctx: StageContext): Promise<{ path: string; bytes: number }> {
    if (input.bytes.byteLength === 0) throw new Error("IMAGE_STORE_EMPTY: no bytes to store");
    const path = imagePath(input.slug, input.variant, input.mime);
    this.files.set(path, { bytes: input.bytes, mime: input.mime });
    return { path, bytes: input.bytes.byteLength };
  }
}

export function createLocalImageStore(options: { dir: string }): ImageStore {
  return {
    kind: "local",
    async put(input: ImageStoreInput, _ctx: StageContext) {
      if (input.bytes.byteLength === 0) throw new Error("IMAGE_STORE_EMPTY: no bytes to store");
      const path = imagePath(input.slug, input.variant, input.mime);
      const file = join(options.dir, path.replace(/^\/images\/generated\//, ""));
      await mkdir(dirname(file), { recursive: true });
      await writeFile(file, input.bytes);
      return { path, bytes: input.bytes.byteLength };
    },
  };
}

/** Error code the static store throws; the placeholder adapter answers it with the static brand placeholder. */
export const IMAGE_STORE_STATIC = "IMAGE_STORE_STATIC";

/**
 * For runs whose publications are served (non-dry-run): there is no durable image host yet, so nothing is
 * stored and no generated path can reach a publication row. The placeholder adapter catches the refusal and
 * returns the static brand placeholder (provenance model `static`).
 */
export function createStaticImageStore(): ImageStore {
  return {
    kind: "static",
    async put(_input: ImageStoreInput, _ctx: StageContext): Promise<{ path: string; bytes: number }> {
      throw new Error(`${IMAGE_STORE_STATIC}: no durable image host for served runs; the static brand placeholder is used`);
    },
  };
}
